  "You too! Have a good day.": "content/audio/you-too-have-a-good-day-c2e89aa2.m4a",
  "Bye, whatever.": "content/audio/bye-whatever-5c28ae13.m4a",
  "How did it go at the library?": "content/audio/how-did-it-go-at-the-library-ba3053db.m4a",
  "We found a real connection.": "content/audio/we-found-a-real-connection-cf385c2b.m4a",
  "We found nothing.": "content/audio/we-found-nothing-e70df3b6.m4a",
